"use client";

import { Children, createContext, useState } from "react";

export const Data = createContext([]);

export default function DataContext({ Children }) {
  const [totalStudents, setTotalStudents] = useState(0);

  return (
    <Data.Provider
      value={{
        totalStudents,
        setTotalStudents,
      }}
    >
      {Children}
    </Data.Provider>
  );
}
